            let mut trans: xmlRegTransPtr =
                (*state).trans.offset(nrtrans as isize) as xmlRegTransPtr;
            if (*trans).atom == atom
                && (*trans).to == (*target).no
                && (*trans).counter == counter
                && (*trans).count == count
